72	pub fn plan_version<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
73	    ws: &Workspace<'_, R, D>,
74	    inference: &I,
75	    opts: &VersionOptions,
76	) -> Result<VersionPlan, GraphError> {
77	    let base_versions = ws.base_versions()?;
78	    let tags = ws.tags()?;
79	
80	    let pre_path = ws.root.join(ws.config.pre_json_path());
81	    let pre_text = callisto_model::strict_fs::read_optional(&pre_path)
82	        .map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
83	    let (pre_state, pre_json_original_text) = if let Some(text) = pre_text {
84	        let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
85	        let state = ws.resolve_pre_state_from_json(state, &text)?;
86	        (Some(state), Some(text))
87	    } else {
88	        (None, None)
89	    };
90	
91	    let mut agg = aggregate(
92	        &ws.graph,
93	        &ws.identity,
94	        &ws.config,
95	        ws.git_access(),
96	        tags,
97	        &base_versions,
98	        pre_state.as_ref(),
99	        inference,
100	    )?;
101	
102	    // For PreMode::Exit, inject a synthetic Patch severity for every package
103	    // that is currently at a pre-release version. This triggers bump_target
104	    // (which in Exit mode calls versioning.bump on the pre-release, stripping
105	    // the tag and finalizing to stable) even when no pending changeset files
106	    // exist on disk — they were consumed and deleted during the pre-release phase
107	    // and their stems recorded in pre.json.
108	    if let Some(ref pre) = pre_state
109	        && pre.mode == callisto_model::format::PreMode::Exit
110	    {
111	        for (id, ver) in &base_versions {
112	            if ver.is_prerelease() {
113	                agg.severities.entry(id.clone()).or_insert(Severity::Patch);
114	                agg.reasons
115	                    .entry(id.clone())
116	                    .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
117	            }
118	        }
119	    }
120	
121	    let input = CascadeInput {
122	        graph: &ws.graph,
123	        groups: &ws.config.groups,
124	        cfg: &ws.config.cascade,
125	        seed: &agg.severities,
126	        reasons: &agg.reasons,
127	        named_by: &agg.named_by,
128	        base: &base_versions,
129	        pre: pre_state.as_ref(),
130	        tags,
131	        identity: &ws.identity,
132	    };
133	
134	    let napi = crate::napi::NapiTargetsIndex::load(&ws.config.groups, &ws.root, &ws.graph)?;
135	    let group_check =
136	        crate::groups::pre_mutation_checks(&ws.graph, &ws.config.groups, &base_versions, tags, &napi, &ws.root)?;
137	
138	    let outcome = run_cascade(input)?;
139	
140	    let mut bumps = Vec::new();
141	    let mut changelog_writes = Vec::new();
142	
143	    // PERF-006: build a map once so each lookup inside the loop is O(1)
144	    // instead of O(N) (the previous packages().find() call).
145	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
146	
147	    for (id, &sev) in &outcome.severities {
148	        if sev == Severity::None {
149	            continue;
150	        }
151	        let pkg = pkg_map
152	            .get(id)
